var a={lines:{cStart:["Buenas noches desde la sala de columnas. Ajedrez: {p} con las blancas, {q} con las negras. Un saludo cordial, y el reloj puede ponerse en marcha.","Silencio en la sala, por favor. {p} juega con blancas y {q} con negras. Veamos qu\xE9 han preparado en casa."],cOpen:["{name}. {idea}","Apertura: {name}. {idea}","Tenemos sobre el tablero {name}. {idea}"],cBlunder:["\xA1Vaya! Eso deja escapar mucho, y {p} quiz\xE1 ya lo note. A los mejores les pasa.","Me temo que es un error serio de {p}. La posici\xF3n se manten\xEDa tan bien.","Un instante de ceguera, y la evaluaci\xF3n da un vuelco. {p} querr\xE1 recuperar esa jugada."],cMistake:["No es lo m\xE1s exacto. {q} se sentir\xE1 algo m\xE1s c\xF3modo ahora.","Una peque\xF1a concesi\xF3n. Creo que {p} ten\xEDa algo m\xE1s ordenado.","Jugable, pero deja a {q} con una ventaja.","Una jugada natural, aunque no del todo la mejor.","Afloja algo. Veamos si {q} est\xE1 de acuerdo.","Yo habr\xEDa mantenido m\xE1s tensi\xF3n en ese punto."],cGone:["Y la ocasi\xF3n queda sin castigo. El ajedrez perdona, de vez en cuando.","La puerta estuvo abierta un momento, y volvi\xF3 a cerrarse."],cBest:["Exactamente as\xED. {p} encuentra la casilla adecuada.","Una jugada muy precisa de {p}. Podr\xEDa aparecer en un manual.","Esa es la jugada: tranquila, exacta y fuerte.","Paciente y exacta. {p} comprende esta posici\xF3n."],cSac:["\xA1Un sacrificio! {p} entrega material por actividad, y parece s\xF3lido.","{p} ofrece una pieza. Audaz y, por lo que alcanzo a ver, correcto."],cFork:["Horquilla: {piece} contra dos objetivos.","Ataque doble: {piece} en dos direcciones a la vez. Una horquilla."],cPin:["Una clavada. La pieza defensora no puede moverse: el rey queda detr\xE1s.","Clavada contra el rey. Una pieza inc\xF3moda de tener."],cPinQ:["Una clavada contra la dama. Puede moverse, pero a un precio."],cSkewer:["Una enfilada. El rey debe apartarse, y lo que hay detr\xE1s cae."],cDisc:["Jaque a la descubierta. La pieza que se movi\xF3 queda libre para hacer lo que quiera."],cSeventh:["Una torre en la s\xE9ptima fila. Nimzowitsch lo aplaudir\xEDa.","La torre llega a la s\xE9ptima, entre los peones. Un viejo sue\xF1o de toda torre."],cOutpost:["Un puesto avanzado para el caballo. Ning\xFAn pe\xF3n lo expulsar\xE1.","Qu\xE9 caballo. Bien asentado, y que irradia."],cFile:["La torre toma la columna abierta. Las columnas son autopistas."],cFian:["Un fianchetto. El alfil mira por la diagonal larga como quien mira por un telescopio."],cPassed:["El pe\xF3n pasado empieza a correr. Como dijo Nimzowitsch, es un delincuente que hay que tener bajo siete llaves.","Un pe\xF3n pasado, y con ambiciones."],cStorm:["Los peones avanzan contra el rey. Se avecina una tormenta."],cCastle:["{p} enroca. El rey a salvo, la torre a trabajar.","Enrocado. Todos los libros de aperturas respiran aliviados."],cOpposite:["Han enrocado en lados opuestos. Se prev\xE9 una carrera: gana quien llegue antes al rey contrario."],cQueens:["Las damas han salido del tablero. Ahora se trata de estructura y paciencia.","Damas cambiadas. Los reyes pueden salir a tomar aire."],cMate:["\xA1Jaque mate! Gana {w}, y la sala se pone en pie.","Y ese es el mate. Un final magn\xEDfico de {w}."],cStale:["\xA1Ahogado! Sin jaque, y sin movimientos. Tablas, y qu\xE9 historia."],cResign:["{q} detiene el reloj y tiende la mano. Una rendici\xF3n elegante. Gana {w}."],cTime:["\xA1Cae la bandera! El reloj decide, y {w} se lleva el punto."],cDraw:["Tablas, {how}. Honor para ambos.","Reparten el punto, {how}. Un relato justo del juego."],cEven:["El equilibrio se mantiene.","Igualados, en lo que puedo juzgar.","Ninguno de los dos bandos puede reclamar nada todav\xEDa."],cSlight:["Una leve ventaja para {p}, nada m\xE1s.","Preferir\xEDa las piezas {side}, pero por muy poco.","Si acaso, {p} est\xE1 un poco m\xE1s c\xF3modo."],cClear:["{p} est\xE1 claramente mejor ahora. Alrededor de {pct} por ciento para llevarse el punto.","La ventaja es real: {p} tiene la partida m\xE1s f\xE1cil.","Las piezas de {p} simplemente hacen m\xE1s."],cWon:["{p} deber\xEDa ganar. Pero todav\xEDa hay que ganarla.","En cualquier marcador {p} va muy por delante. Ahora, t\xE9cnica."],cNet:["La red se cierra. No veo salida.","Puede haber un final forzado aqu\xED."],cTense:["Cuidado ahora. Es una de esas posiciones en que todo depende de una sola jugada.","No dir\xE9 nada, solo que la sala se ha quedado muy callada."],cPlanOpenC:["El centro est\xE1 abierto. Los alfiles y un desarrollo r\xE1pido ser\xE1n lo m\xE1s importante."],cPlanLocked:["El centro est\xE1 cerrado. La partida ir\xE1 a las alas, con rupturas de peones y caballos."],cPlanIqp:["Un pe\xF3n de dama aislado: actividad en el medio juego, carga en el final. {p} deber\xEDa jugar con piezas, y pronto."],cPlanPair:["{p} tiene la pareja de alfiles. En una posici\xF3n abierta, eso vale medio pe\xF3n."],cPlanDbl:["Peones doblados para {p}. Una debilidad para quien espera, una columna abierta para quien act\xFAa."],cEndPawns:["Final de peones. Ahora mandan la oposici\xF3n, el tempo y la aritm\xE9tica. Una sola jugada de rey decide."],cEndRooks:["Final de torres. Dicen que todos son tablas. No lo son si se est\xE1 defendiendo."],cEndOpp:["Alfiles de colores opuestos. El gran recurso de tablas, incluso con un pe\xF3n o dos de menos."],cEndQueens:["Final de damas: largo, nervioso, lleno de jaques."],cEndMinor:["Piezas menores y peones. El bando con mejor rey suele tener la \xFAltima palabra."],cEndSome:["Entramos en el final. El rey ya es una pieza de combate."],sSolid:["{p} juega con una contenci\xF3n admirable. Hasta ahora, apenas una jugada floja.","Una partida limpia y cl\xE1sica de {p}. Capablanca lo aprobar\xEDa."],sSharp:["{p} busca complicaciones en cada turno. Hay un poco de Tal en ello.","{p} juega al ataque, y lo disfruta."],sWarm:["{p} ha tenido momentos irregulares, pero no deja de plantear problemas. Eso es juego de luchador.","No es una partida perfecta de {p}, pero s\xED honesta, y no ha terminado."],sQuick:["{p} juega r\xE1pido. Confianza, o buena preparaci\xF3n."],sSlow:["{p} invierte bastante tiempo. El reloj tambi\xE9n es una pieza."],sBoth:["Buen duelo. {p} construye, {q} espera un objetivo. Creo que el medio juego lo decidir\xE1.","Dos temperamentos distintos: {p} empuja, {q} absorbe. Veamos qui\xE9n aguanta m\xE1s."],bStart:["Buenas noches. Backgammon, {len}. {p} contra {q}. Un dado cada uno, y el mayor empieza.","El tablero est\xE1 listo, y los dados, templados. {p} se enfrenta a {q}, {len}."],bRoll:["{p} tira {roll}."],bDouble6:["\xA1Doble seis! Ha llegado la gran tirada para {p}."],bDouble5:["Dobles cincos. Una tirada fuerte y sencilla, si los puntos est\xE1n abiertos."],bDouble4:["Dobles cuatros para {p}. Una forma preciosa."],bDouble3:["Dobles treses. Algunos dicen que es la tirada m\xE1s bonita del tablero."],bDouble2:["Dobles dos, una tirada de constructor."],bDouble1:["Dobles ases. Peque\xF1a, pero muchas partidas se han decidido por ella."],bDance:["{p} baila. Nada entra, y {q} sigue tirando.","Cerrado por ahora: {p} se queda en la barra."],bOpen31:["Tres y uno: el punto cinco, de inmediato. La mejor tirada de apertura que existe."],bJoker:["Qu\xE9 tirada. Un comod\xEDn, si alguna vez lo hubo.","Los dados sonr\xEDen a {p}. Eso lo cambia todo."],bUnlucky:["Los dados fueron poco amables ah\xED. {p} sac\xF3 lo mejor de muy poco.","No es el n\xFAmero que {p} esperaba."],bBlunder:["Hmm. Creo que hab\xEDa algo mejor en esa tirada. {p} deja algo sobre la mesa.","Una elecci\xF3n costosa, en equity. Aunque requiere valor.","Habr\xEDa buscado algo m\xE1s seguro, pero {p} tiene un plan propio.","La tirada daba m\xE1s de s\xED. Estas son las decisiones que solo parecen peque\xF1as.","Una lectura audaz de esa tirada. Los n\xFAmeros prefieren otra."],bGood:["Bien jugado. De {n} maneras de jugarla, {p} eligi\xF3 la m\xE1s s\xF3lida.","Correcto, y no obvio.","Una jugada que solo se encuentra con experiencia.","Tranquila y acertada."],bHit:["\xA1Golpe! {q} va a la barra.","{p} recoge la ficha suelta y gana el tempo.","Contacto, y {q} debe entrar antes que nada.","{p} golpea. Veintitantos pips perdidos de un plumazo para {q}."],bHit2:["Dos fichas sueltas golpeadas en un turno. {q} tiene mucho que reconstruir."],bFive:["El punto cinco, el punto de oro. {p} vivir\xE1 de \xE9l durante un rato."],bBar5:["Hecho el punto de barra. Un ladrillo m\xE1s en el muro."],bAnchor:["Un ancla avanzada. {p} puede permitirse algo de riesgo ahora.","Con esa ancla, {p} ya no sufrir\xE1 un blitz."],bPrime5:["Un prime de cinco puntos. Solo un seis en el extremo lo supera."],bPrime6:["Un prime completo. Seis seguidos: nada pasa, digan lo que digan los dados."],bShots:["{q} tiene {n} tiradas de golpe de las treinta y seis. {odds}","{n} n\xFAmeros golpean. {odds}","{q} mira {n} tiradas que golpean.","Treinta y seis tiradas, {n} de ellas problem\xE1ticas para {p}. {odds}"],bOddsLow:["Un riesgo peque\xF1o, tomado con sensatez.","Bien calculado.","Con eso se puede dormir tranquilo."],bOddsMid:["M\xE1s o menos lo que se paga en este negocio.","Un riesgo justo.","Algo as\xED como una de cada tres. As\xED es el backgammon."],bOddsHigh:["Eso es vivir peligrosamente.","Conviene agarrarse a la silla.","M\xE1s vale que valga la pena."],bTypeRace:["Se ha roto el contacto: carrera pura. {p} lleva {d} pips de ventaja.","Ahora es una carrera. {p} va {d} pips por delante; el desgaste decidir\xE1 el resto."],bTypeRaceEven:["Carrera perfectamente igualada. De aqu\xED en adelante, solo los dados."],bTypeBlitz:["Hay blitz. {p} ataca cada ficha suelta antes de que pueda formarse un ancla."],bTypePrime:["El prime hace el trabajo. {p} solo tiene que llevarlo a casa con buen orden."],bTypePrimes:["Prime contra prime. El timing lo es todo: pierde quien deba romper primero."],bTypeHolding:["Un juego de ancla. {p} mantiene el ancla y espera un golpe."],bTypeMutual:["Un juego de anclas mutuo. Paciencia, y el primer doble grande."],bTypeBack:["Un juego de puntos atrasados. {p} tiene dos anclas y necesita el timing. Rom\xE1ntico, y arriesgado."],bTypeAce:["Un juego del punto del as: quiz\xE1 un \xFAltimo golpe. Unos diecisiete por ciento, seg\xFAn los libros."],bWin:["{p} tiene alrededor de {pct} por ciento de ganar esta partida.","Yo lo calculo en {pct} por ciento para {p}."],bEven:["Dif\xEDcilmente podr\xEDa estar m\xE1s igualado.","Igualados, o lo m\xE1s cerca posible."],bMarket:["{q} est\xE1 cerca de perder el mercado. El cubo estar\xE1 en la mente de alguien."],bDbl:["{p} gira el cubo. Un doble de manual: fuerte, y el mercado estaba a punto de irse.","El cubo pasa a {v}. Bien elegido, creo."],bDblEarly:["Un doble temprano de {p}. Plantea una pregunta, y hay respuesta."],bDblBig:["{p} dobla. Eso bien puede ser un pase."],bTake:["Aceptado. Con un cuarto de las posibilidades se puede, y {p} tiene eso y m\xE1s.","Una aceptaci\xF3n correcta."],bTakeBrave:["\xA1Aceptado! Un cubo valiente de sostener. {p} cree en los dados."],bDrop:["Pasado. Hay que saber cu\xE1ndo retirarse."],bDropEarly:["Pasado. Podr\xEDa haber seguido jugando, pero nadie se arruin\xF3 por ser prudente."],bWinGame:["{w} gana la partida.","Ya est\xE1 en casa: la partida es de {w}."],bGammon:["\xA1Gammon! {w} cuenta el doble.","Gammon. {w} saca todas sus fichas antes de que {q} saque ni una sola."],bBackgammon:["\xA1Backgammon! Tres veces el cubo. No se ve eso todas las noches."],bMatch:["Y el encuentro es para {w}. Bien disputado, por ambos."],bCrawford:["La partida de Crawford: sin cubo esta vez, a un punto de la victoria."],bStyleBold:["A {p} le gusta golpear y asumir riesgos. Un estilo audaz, que paga cuando los dados acompa\xF1an."],bStyleSafe:["{p} juega seguro y espera. Pocas fichas sueltas, pocos remordimientos."],bStyleLuck:["Los dados han favorecido a {p} hasta ahora. La suerte forma parte del juego; usarla bien es la habilidad."],bStyleGood:["{p} apenas ha desperdiciado un pip. Un backgammon muy s\xF3lido."],kStart:["Buenas noches. {name}. {p} mueve primero. Aqu\xED la captura no es una opci\xF3n: es la ley.","El tablero est\xE1 preparado para {name}. {p} empieza, {q} responde."],kShot:["\xA1Un golpe! {n} fichas en una sola barrida.","{p} salta {n} de una vez. Qu\xE9 combinaci\xF3n."],kTwoForOne:["Dos por una. {p} lo ten\xEDa calculado."],kTrade:["Un intercambio. Cuantas menos fichas, m\xE1s pesa cada tempo.","Ficha por ficha. Ahora importa m\xE1s la estructura."],kCrown:["\xA1Dama! {p} ha llegado, y ahora el tablero juega en ambos sentidos.","Dama conseguida. {p} disfrutar\xE1 de la libertad."],kBlunder:["Me temo que eso abre una puerta.","Una jugada floja. {q} lo habr\xE1 notado.","{q} podr\xEDa tener ah\xED su oportunidad muy pronto.","La formaci\xF3n se afloja un poco.","No es la m\xE1s firme. Las damas castigan despacio, pero castigan."],kGood:["Una jugada paciente y correcta.","Buena forma. {p} mantiene las fichas juntas, como debe ser.","Tempo conservado, nada regalado.","{p} espera a que el otro se comprometa. Muy maduro."],kGuard:["{p} a\xFAn conserva la \xFAltima fila. Nadie consigue una dama gratis."],kOpen:["La \xFAltima fila se abre para {p}. Atenci\xF3n a la esquina doble."],kAhead:["{p} va por delante, {a} contra {b}. Los cambios favorecen al bando m\xE1s fuerte."],kEven:["{a} fichas cada uno. Todo depender\xE1 de la jugada, de la oposici\xF3n.","Empate total. Quien se quede sin jugadas seguras primero lo sufrir\xE1."],kEnd:["Un final con damas. Parece sencillo, y nunca lo es."],kWin:["Y ya est\xE1. Gana {w}, con todas las fichas contabilizadas."],kDraw:["Tablas. Las damas bien defendidas suelen terminar as\xED, y no es ninguna verg\xFCenza."],gStart:["Buenas noches. Bridge, con {n}. Norte y Sur contra Este y Oeste. Se reparte la primera mano."],g1NT:["Un sin triunfo: de quince a diecisiete, equilibrado. El compa\xF1ero ya sabe casi todo."],g1M:["{bid}: cinco cartas y una mano de apertura.","{p} abre {bid}. Una mayor de cinco cartas."],g1m:["{p} abre {bid}. La menor m\xE1s larga, y todo por descubrir."],g2C:["Dos tr\xE9boles, el fuerte. Nadie lo pasa a la ligera por debajo de manga."],g2NT:["Dos sin triunfo: de veinte a veintiuno, y equilibrado."],gWeak:["Un dos d\xE9bil. Seis cartas, pocos puntos y un obst\xE1culo para los dem\xE1s."],gPre:["Una apertura de interferencia de {p}. Palo largo, poca defensa. Les quita espacio para hablar."],gStayman:["Stayman: \xBFtiene el compa\xF1ero una mayor de cuatro cartas?"],gTransfer:["Una transferencia. La mano fuerte ser\xE1 la declarante, y quedar\xE1 oculta."],gTake:["Contra de castigo: el compa\xF1ero elige palo."],gOver:["{p} entra con {bid}. Un palo para salir, como m\xEDnimo."],gRaise:["Subida. Han encontrado su fit.","Apoyo de {p}. Ocho bazas de triunfo como m\xEDnimo, creo."],gInvite:["Una invitaci\xF3n a manga. El compa\xF1ero mira el \xFAltimo punto dos veces."],gGame:["{bid}: manga. No hay m\xE1s preguntas.","Y {p} juega la manga, {bid}."],gSlam:["\xA1{bid}! Un slam. Doce bazas o nada."],gGrand:["\xA1{bid}! El gran slam. Cada una de las bazas."],gDouble:["Contra. {p} no se lo cree."],gRedouble:["\xA1Recontra! Nervios de acero."],gContract:["{contract}. Se necesitan {need} bazas. Sale {lead}.","El contrato es {contract}: {need} bazas para {p}. Sale {lead}."],gPartScore:["Una manga parcial. Estos contratos peque\xF1os deciden las partidas largas."],gLeadTop:["Salida: {card}. Tal vez de una secuencia alta, o buscando la ayuda del compa\xF1ero."],gLeadLow:["Una carta baja: la cuarta del palo m\xE1s largo, dicen los libros."],gLeadTrump:["Salida de triunfo, para reducir los fallos."],gLead:["Sale {card}."],gDummyGood:["El muerto se pone con {n} puntos. Una vista agradable para el declarante.","{n} puntos en el muerto. Hay material aqu\xED."],gDummyThin:["Solo {n} puntos en el muerto. El declarante tendr\xE1 que gan\xE1rselo."],gDummyRuff:["Vac\xEDo en el muerto, y triunfos. Espero fallos antes de que se saquen los triunfos."],gRuff:["Fallada por {p}.","Un fallo. Los triunfos hacen su trabajo.","{p} no ten\xEDa m\xE1s de ese palo."],gTrumps:["Se sacan los triunfos. Primero, el orden."],gSmall:["Una carta peque\xF1a se lleva la baza. El declarante cont\xF3 ese palo."],gTight:["Ya no quedan bazas que perder. Cada carta cuenta desde aqu\xED.","Todo se decide en las \xFAltimas cartas: ni una baza de margen."],gEasy:["El contrato parece seguro. Ahora, las sobrebazas."],gDoomed:["La defensa tiene suficiente. Solo es cuesti\xF3n de cu\xE1ntas."],gMadeIt:["Ese es el contrato, con bazas en la mano."],gMade:["Hecho justo. {n} para {side}.","Contrato cumplido, {n} para {side}."],gOverT:["Hecho con {d} de margen: {n} para {side}."],gDown:["Batido por {d}. {n} para la defensa.","{d} de castigo. Buena defensa, y la paciencia tiene recompensa."],gSlamMade:["\xA1El slam est\xE1 hecho! Una mano para recordar."],gPassed:["Todos pasan. A nadie le gust\xF3 lo que vio."],gEnd:["\xDAltimo tablero. Gana {side}, {score}."],gTie:["Todos los tableros jugados, y sin diferencia entre ellos."],pStart:["Una tarde tranquila. {name}. Sin prisas, {p}: las cartas no tienen ninguna."],pFree:["FreeCell, reparto n\xFAmero {n}. Todo est\xE1 a la vista: aqu\xED no hay suerte, solo planificaci\xF3n."],pHome:["La primera ya est\xE1 en casa.","Un as llega a casa. Un comienzo."],pEmpty:["Una columna vac\xEDa. Lo m\xE1s valioso de la mesa: conviene aprovecharla bien.","Se abre una columna. Espacio para respirar."],pTurn:["Sale otra carta a la luz.","Una menos en la oscuridad."],pDownLeft:["{n} cartas siguen boca abajo."],pAllUp:["Todo est\xE1 boca arriba. Desde aqu\xED deber\xEDa resolverse solo."],pCells:["Las cuatro celdas est\xE1n llenas. Ahora cada jugada debe liberar algo.","No queda celda libre. Respira y busca el camino de vuelta."],pCellsFree:["Las celdas est\xE1n libres de nuevo. Bien desenredado."],pHalf:["La mitad del mazo ya est\xE1 en casa. Va bien."],pNear:["Quedan pocas. Huele a victoria."],pPass:["Otra pasada por el mont\xF3n. Al fin y al cabo, la paciencia es el juego."],pDeep:["Los ases est\xE1n escondidos en el fondo de este reparto. Habr\xE1 que cavar."],pShallow:["Las cartas bajas est\xE1n cerca de la superficie. Un reparto amable."],pSolved:["\xA1Resuelto! Cada carta en su sitio. Muy bien hecho, {p}.","Y ah\xED est\xE1: orden surgido del caos, en {n} jugadas."]},ideas:["Las negras luchan por el centro desde el flanco, y es probable una partida viva.","S\xF3lido, con un problema: el alfil de c8.","S\xF3lido como un banco. El alfil sale antes de que se cierre la puerta.","La tortura espa\xF1ola: presi\xF3n lenta sobre el centro durante cuarenta jugadas.","Viejas ideas italianas: desarrollo r\xE1pido, y la vista puesta en f7.","Regresa la \xE9poca rom\xE1ntica. Un pe\xF3n por las l\xEDneas abiertas.","Simetr\xEDa, y una lucha por la primera iniciativa.","Las negras dejan que las blancas construyan el centro, e intentar\xE1n hacerlo saltar por los aires.","La batalla gira en torno a la casilla e4, y al alfil frente al caballo.","Una lucha por el centro a lo grande.","Una respuesta moderna: ceder el centro, y luego atacarlo.","Las negras juegan por el flanco de rey desde la primera jugada.","Una apertura de flanco. El centro se decidir\xE1 m\xE1s tarde.","Ambos conocer\xE1n bien esta."],lore:["Los peones son el alma del ajedrez, escribi\xF3 Philidor en mil setecientos cuarenta y nueve. Dos siglos y medio despu\xE9s, nadie lo ha contradicho.","La palabra mate viene del persa: el rey queda indefenso.","El primer campe\xF3n sovi\xE9tico fue Alexander Alekhine, en Mosc\xFA, en mil novecientos veinte.","En ruso el alfil es un elefante, y en turco tambi\xE9n; el nuestro, de origen \xE1rabe, guarda ese recuerdo. Solo los ingleses lo mandaron a la iglesia.","Tartakower lo dijo mejor: gana quien comete el pen\xFAltimo error.","Antes de los relojes, las partidas pod\xEDan durar hasta que alguien se durmiera. Los relojes mec\xE1nicos de dos esferas pusieron fin a eso en la d\xE9cada de 1880.","En 1985 Garry Kasp\xE1rov se convirti\xF3 en campe\xF3n del mundo en Mosc\xFA, con veintid\xF3s a\xF1os.","Se pulsa el reloj con la mano que movi\xF3 la pieza. Est\xE1 en las Reglas, y es de buena educaci\xF3n.","El cubo de doblar naci\xF3 en los clubes de Nueva York en los a\xF1os veinte. Nadie sabe qui\xE9n lo ide\xF3.","En 1992 un programa llamado TD-Gammon aprendi\xF3 backgammon jugando contra s\xED mismo, y cambi\xF3 la forma en que la gente abre.","Treinta y seis tiradas, y once de ellas contienen el n\xFAmero que se nombre.","En una mesa turca, los dados siguen hablando persa: yek, d\xFC, se, cihar, pen\xE7, \u015Fe\u015F.","Cada bando empieza con ciento sesenta y siete pips por recorrer. Una tirada media avanza algo m\xE1s de ocho.","Tableros con dados y dos filas de puntos se juegan desde hace unos cinco mil a\xF1os. La discusi\xF3n sobre la suerte es igual de antigua.","En 2007 el equipo de Jonathan Schaeffer lo demostr\xF3: con juego perfecto, las damas inglesas son tablas.","Marion Tinsley, el mayor jugador de damas, perdi\xF3 solo un pu\xF1ado de partidas en m\xE1s de cuarenta a\xF1os.","Las damas en tablero de diez por diez se llaman casi en todas partes \xABpolacas\xBB, excepto en Polonia.","En shashki la dama vuela por toda la diagonal. Los viejos maestros la llamaban el brazo largo.","Harold Vanderbilt dio forma al bridge de contrato durante un crucero por el canal de Panam\xE1 en 1925.","Hay m\xE1s de seiscientos mil millones de manos distintas de trece cartas. Nunca volver\xE1 a verse esta.","Ocho siempre, nueve nunca: con ocho cartas y la dama que falta, imp\xE1s. Con nueve, se juega para la ca\xEDda. La mayor\xEDa de las veces.","En el duplicado nadie tiene buenas ni malas cartas. Todos reciben las mismas manos, y solo se compara el juego.","De los treinta y dos mil repartos cl\xE1sicos de FreeCell, uno solo no pudo resolverse nunca: el n\xFAmero once mil novecientos ochenta y dos.","Klondike toma su nombre de los campos de oro de Canad\xE1. El azar es m\xE1s o menos el mismo.","En ruso y en franc\xE9s, toda esta familia de juegos se llama paciencia. Una advertencia justa.","Paul Alfille escribi\xF3 el primer FreeCell para computadora siendo estudiante, en 1978."],w:{pieces:["","pe\xF3n","caballo","alfil","torre","dama","rey"],white:"blancas",black:"negras",ns:"Norte\u2013Sur",ew:"Este\u2013Oeste",nt:"sin triunfo",dbl:[""," doblado"," redoblado"],suits:["tr\xE9boles","diamantes","corazones","picas"],honours:{T:"diez",J:"jota",Q:"dama",K:"rey",A:"as"},card:"{rank} de {suit}",single:"una sola partida",match:"un match a {n}",board1:"un solo tablero",boards:"{n} manos",english:"damas inglesas",russian:"damas rusas",international:"damas internacionales",klondike:"Klondike",computer:"la computadora",stalemate:"por ahogado",agreed:"por acuerdo mutuo",threefold:"por triple repetici\xF3n",fivefold:"por repetici\xF3n",moves50:"por la regla de las cincuenta jugadas",moves75:"por la regla de las setenta y cinco jugadas",dead:"sin material para dar mate",timedead:"aunque cay\xF3 una bandera",quiet:"con damas dando vueltas",fewkings:"con muy pocas damas para ganar"}};export{a as default};
